      description:
        'Direction the rule runs: `horizontal` draws a full-width line, `vertical` a full-height one that stretches to its flex row.',
      type: "'horizontal' | 'vertical'",
      required: false,
      default: 'horizontal',
    },
    {
      name: 'decorative',
      type: 'boolean',
      required: false,
      default: 'false',
      description: 'When true, the separator is purely visual and hidden from assistive tech',
    },
  ],
  tokens: ['--cascivo-color-border'],
  accessibility: {
    role: 'separator',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Horizontal', code: '<Separator />' },
    { title: 'Vertical', code: '<Separator orientation="vertical" />' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['divider', 'rule', 'layout'],
  intent: {
    whenToUse: [
      'Dividing groups of content within a section or menu',
      'Adding a vertical rule between inline items (orientation="vertical")',
